import{_ as t,c as o,o as a,ag as n}from"./chunks/framework.B-XtCDNB.js";const u=JSON.parse('{"title":"2. Command Line Tool","description":"2. Command Line Tool ::: warning Warning The valadoc command line tool may not be bundled with your installation of the Vala. You will need to find a way to install it on your operating system. :::...","frontmatter":{"prev":{"text":"1. Quick Start","link":"/guides/valadoc-guide/01-00-quick-start"},"next":{"text":"3. Documentation Comment Markup","link":"/guides/valadoc-guide/03-00-documentation-comment-markup"}},"headers":[],"relativePath":"guides/valadoc-guide/02-00-command-line-tool.md","filePath":"guides/valadoc-guide/02-00-command-line-tool.md","lastUpdated":1786207193000}'),l={name:"guides/valadoc-guide/02-00-command-line-tool.md"};function s(i,e,d,c,r,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_2-command-line-tool" tabindex="-1">2. Command Line Tool <a class="header-anchor" href="#_2-command-line-tool" aria-label="Permalink to &quot;2. Command Line Tool&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>The <code>valadoc</code> command line tool may not be bundled with your installation of the Vala. You will need to find a way to install it on your operating system.</p></div><p>Usage:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">valadoc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [OPTION...] FILE...</span></span></code></pre></div><h2 id="_2-1-essential-options" tabindex="-1">2.1. Essential Options <a class="header-anchor" href="#_2-1-essential-options" aria-label="Permalink to &quot;2.1. Essential Options&quot;">​</a></h2><p><strong>-o,--directory=DIRECTORY</strong></p><blockquote><p>Output directory of the generated documentation.</p><p>The name of the directory will also be used as the package name if a package name has not been explicitly set and cannot be derived from any other sources</p></blockquote><p><strong>--package-name=NAME</strong></p><blockquote><p>Sets the name of the package of the generated documentation.</p></blockquote><p><strong>--package-version=VERSION</strong></p><blockquote><p>Sets the package version of the generated documentation.</p></blockquote><p><strong>--force</strong></p><blockquote><p>Force the documentation to be generated, even if the output directory already exists.</p><p>As stated in the <a href="./../valadoc-guide/01-00-quick-start.html">quick start guide</a>, with this option set, generated documentation is only added or overwritten.</p></blockquote><p><strong>--pkg=PACKAGE...</strong></p><blockquote><p>Specify bindings to include in the documentation via their package names.</p></blockquote><p><strong>--version</strong></p><blockquote><p>Display the version number of the valadoc tool.</p></blockquote><p><strong>-h, --help</strong></p><blockquote><p>View the list of all of the commands and options that <code>valadoc</code> supports.</p><p>You&#39;ll see additional options that aren&#39;t listed on this page when you use this option.</p></blockquote><h2 id="_2-2-doclets" tabindex="-1">2.2. Doclets <a class="header-anchor" href="#_2-2-doclets" aria-label="Permalink to &quot;2.2. Doclets&quot;">​</a></h2><p>A doclet controls the output format of the documentation that <code>valadoc</code> generates. Select one with the <code>--doclet</code> option:</p><p><strong>--doclet=NAME</strong></p><blockquote><p>Selects the doclet used to generate the documentation, by name or by path to a custom doclet. If this option isn&#39;t set, <code>valadoc</code> uses the <code>html</code> doclet.</p></blockquote><p><strong>-X, --doclet-arg=ARG</strong></p><blockquote><p>Passes an argument through to the selected doclet. Some doclets, such as <code>gtkdoc</code>, accept their own set of options this way. Run <code>valadoc -X --help</code> to see the arguments a doclet supports.</p></blockquote><p><code>valadoc</code> includes the following doclets:</p><h3 id="_2-2-1-html" tabindex="-1">2.2.1. html <a class="header-anchor" href="#_2-2-1-html" aria-label="Permalink to &quot;2.2.1. html&quot;">​</a></h3><blockquote><p>Generates a standard set of HTML pages, such as the documentation generated in the <a href="./../valadoc-guide/01-00-quick-start.html">quick start guide</a>. This is the default doclet, so you don&#39;t need to pass <code>--doclet</code> to use it.</p></blockquote><h3 id="_2-2-2-devhelp" tabindex="-1">2.2.2. devhelp <a class="header-anchor" href="#_2-2-2-devhelp" aria-label="Permalink to &quot;2.2.2. devhelp&quot;">​</a></h3><blockquote><p>Generates documentation for local API browsers. Alongside the HTML pages, it writes a <code>.devhelp2</code> index file for each package so that these browsers can find and search the documentation locally.</p><p>Select it with <code>--doclet=devhelp</code>.</p><p><a href="https://apps.gnome.org/Manuals/" target="_blank" rel="noreferrer">GNOME Manuals</a> is the API browser you&#39;ll want to use with this doclet&#39;s output today. It&#39;s part of GNOME&#39;s core developer tools and still reads the devhelp documentation format, so the <code>.devhelp2</code> files this doclet generates work with it out of the box.</p><p><a href="https://wiki.gnome.org/Apps/Devhelp" target="_blank" rel="noreferrer">GNOME Devhelp</a>, the API browser this doclet was originally built for, has since been archived in favor of Manuals.</p></blockquote><h3 id="_2-2-3-gtk-doc" tabindex="-1">2.2.3. gtk-doc <a class="header-anchor" href="#_2-2-3-gtk-doc" aria-label="Permalink to &quot;2.2.3. gtk-doc&quot;">​</a></h3><blockquote><p>Generates output in the <a href="https://gitlab.gnome.org/GNOME/gtk-doc" target="_blank" rel="noreferrer">gtk-doc</a> format, historically used to document C-based GNOME libraries. Newer libraries typically use <a href="https://gnome.pages.gitlab.gnome.org/gi-docgen/" target="_blank" rel="noreferrer">gi-docgen</a> for this purpose instead.</p><p>Select it with <code>--doclet=gtkdoc</code>.</p></blockquote>',32)])])}const g=t(l,[["render",s]]);export{u as __pageData,g as default};
